using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// A sample type we'll resolve metadata for
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// 2) Probe without throwing — TryGetTypeInfo returns bool
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {found!.Type.Name}");
}

// Now try a type that has NO resolver registered (use a bare options with no resolver)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = null   // no resolver at all
};

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? notFound))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on empty options: not available (no exception thrown)");
}

public record Person(string Name, int Age);
EOF
